package eu.motionforge.app.core.render3d

import eu.motionforge.app.core.model.ReviewStatus
import kotlinx.serialization.SerializationException
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.doubleOrNull

/** One animation clip as described by the asset's clip manifest (generated by the Blender build). */
data class ClipInfo(val name: String, val durationSeconds: Float, val reviewStatus: ReviewStatus)

/** Parsed coach clip manifest (`models/coach_*.clips.json`). */
data class ClipManifest(val assetPath: String, val clips: List<ClipInfo>) {
    val names: Set<String> = clips.map { it.name }.toSet()
    fun clip(name: String): ClipInfo? = clips.firstOrNull { it.name == name }

    companion object {
        /** Default coach's manifest (see [eu.motionforge.app.core.model.Coach] for all coaches). */
        const val TRAINER_MANIFEST_PATH = "models/coach_f.clips.json"

        fun parse(text: String): ClipManifest {
            val root = try {
                Json.parseToJsonElement(text) as? JsonObject
            } catch (e: SerializationException) {
                null
            } ?: throw IllegalArgumentException("Clip manifest is not a JSON object")
            val asset = (root["asset"] as? JsonPrimitive)?.takeIf { it.isString }?.content
                ?: throw IllegalArgumentException("Clip manifest has no asset path")
            val clips = (root["clips"] as? JsonArray ?: throw IllegalArgumentException("Clip manifest has no clips")).map { el ->
                val o = el as? JsonObject ?: throw IllegalArgumentException("Clip entry is not an object")
                val name = (o["name"] as? JsonPrimitive)?.content?.takeIf { it.isNotBlank() }
                    ?: throw IllegalArgumentException("Clip without a name")
                val duration = (o["durationSeconds"] as? JsonPrimitive)?.doubleOrNull
                    ?: throw IllegalArgumentException("Clip '$name' has no duration")
                require(duration > 0) { "Clip '$name' has a non-positive duration" }
                val status = (o["reviewStatus"] as? JsonPrimitive)?.content
                val review = ReviewStatus.entries.firstOrNull { it.wireName == status }
                    ?: throw IllegalArgumentException("Clip '$name' has unknown review status '$status'")
                ClipInfo(name, duration.toFloat(), review)
            }
            require(clips.map { it.name }.toSet().size == clips.size) { "Duplicate clip names" }
            return ClipManifest(asset, clips)
        }
    }
}

/**
 * Decides which clips a lesson demonstration plays, in order, and how to label them.
 * Pure Kotlin so it is unit-tested.
 */
object DemoSequence {

    /**
     * - Unknown or missing clip → empty (the UI shows its written fallback instead of a wrong demo).
     * - A "<move>_down" clip with a matching "<move>_up" plays both, so a repetition is complete.
     * - A footwork step plays with its return step, so the drill loops from where it began.
     * - Anything else plays on its own.
     */
    fun resolve(demoAnimation: String?, available: Set<String>): List<String> {
        if (demoAnimation == null || demoAnimation !in available) return emptyList()
        if (demoAnimation.endsWith("_down")) {
            val up = demoAnimation.removeSuffix("_down") + "_up"
            if (up in available) return listOf(demoAnimation, up)
        }
        // A push-step drill steps in and then back out, so the coach ends where it started and the loop has no jump.
        PAIRED_RETURN[demoAnimation]?.let { back -> if (back in available) return listOf(demoAnimation, back) }
        return listOf(demoAnimation)
    }

    private val PAIRED_RETURN = mapOf(
        "footwork_forward" to "footwork_backward",
        "footwork_backward" to "footwork_forward",
    )

    /** Short human label for the movement phase a clip shows. */
    fun phaseLabel(clip: String): String = when {
        clip == "warmup_march" -> "March on the spot"
        clip == "hip_hinge_down" -> "Hips back"
        clip == "hip_hinge_up" -> "Return to standing"
        clip.endsWith("_down") -> "Lowering"
        clip.endsWith("_up") -> "Rising"
        clip == "boxing_stance" -> "Stance"
        clip == "boxing_guard_return" -> "Return to guard"
        clip == "boxing_lead_hook" -> "Lead hook"
        clip == "footwork_lateral" -> "Step side to side"
        clip == "plank_hold" -> "Hold"
        clip == "reverse_lunge" -> "Step back and lower"
        clip == "glute_bridge" -> "Lift and lower"
        clip == "step_jack" -> "Step out, arms up"
        clip == "calf_raise" -> "Rise and lower"
        clip == "dead_bug" -> "Reach opposite arm and leg"
        clip == "bird_dog" -> "Reach opposite arm and leg"
        clip == "cat_cow" -> "Round, then arch"
        clip == "superman" -> "Lift and lower"
        clip == "split_squat" -> "Lower and rise"
        clip == "side_lunge" -> "Side to side"
        clip == "high_knee_march" -> "High-knee march"
        clip == "mountain_climber_slow" -> "Knee to chest"
        clip == "arm_circles" -> "Circle forward, then back"
        clip == "footwork_pivot" -> "Pivot"
        clip == "band_pull_apart" -> "Pull apart"
        clip == "db_curl" -> "Curl"
        clip == "db_shoulder_press" -> "Press"
        clip == "db_lateral_raise" -> "Raise"
        clip == "db_bent_over_row" -> "Row"
        clip in LABELS -> LABELS.getValue(clip)
        clip.startsWith("footwork_") -> "Step " + clip.removePrefix("footwork_").replace('_', ' ')
        else -> clip.substringAfter('_').replace('_', ' ').replaceFirstChar { it.uppercase() }
    }

    private val LABELS = mapOf(
        "good_morning" to "Hips back, then tall", "curtsy_lunge" to "Step back and across", "squat_calf_raise" to "Squat, then rise",
        "single_leg_balance" to "Balance on one leg", "single_leg_rdl" to "Hinge on one leg", "side_leg_raise" to "Leg out to the side",
        "glute_kickback" to "Leg back", "butt_kicks" to "Heels to the seat", "torso_twist" to "Turn side to side",
        "side_bend" to "Reach up and over", "skater_step" to "Side to side", "wall_pushup" to "Lower and press",
        "wall_sit" to "Slide down and hold", "db_goblet_squat" to "Lower and rise", "db_floor_press" to "Press",
        "db_shrug" to "Shoulders up", "db_calf_raise" to "Rise and lower", "kb_swing" to "Hinge and swing",
        "bench_dip" to "Lower and press", "crunch" to "Curl up", "heel_taps" to "Reach to each heel",
        "reverse_crunch" to "Curl the hips", "toe_taps" to "Lower one foot", "high_plank" to "Hold",
        "shoulder_taps" to "Tap each shoulder", "single_leg_bridge" to "Lift on one leg", "donkey_kick" to "Lift the knee back",
        "fire_hydrant" to "Knee out to the side", "childs_pose" to "Sit back and breathe", "bear_hold" to "Knees just off the floor",
        "footwork_circle_left" to "Step left and turn", "footwork_circle_right" to "Step right and turn",
        "footwork_angle_step" to "Step off the line", "footwork_shuffle" to "In and out",
        "boxing_high_block" to "Cover", "boxing_body_block" to "Elbow to the ribs", "boxing_fist_rolls" to "Roll the fists",
        "boxing_stance_bounce" to "Bounce in your stance", "boxing_pull_counter" to "Pull back, then cross",
        "quad_stretch" to "Heel to the seat", "shoulder_stretch" to "Arm across the chest", "triceps_stretch" to "Hand behind the head",
        "chest_opener" to "Hands back, chest up", "hip_flexor_stretch" to "Kneel and press the hips forward",
        "leg_swing" to "Swing from the hip", "hip_circles" to "Slow hip circles", "hamstring_stretch" to "Heel forward, hips back",
        "squat_hold" to "Sit low, chest up", "calf_stretch" to "Back heel down, lean in",
    )

    /**
     * Position inside a looping sequence: returns (index of the clip, time inside that clip).
     * [durations] must be positive. Negative time is treated as 0.
     */
    fun locate(durations: List<Float>, timeSeconds: Double): Pair<Int, Float> {
        require(durations.isNotEmpty()) { "Empty sequence" }
        require(durations.all { it > 0f }) { "Durations must be positive" }
        val total = durations.sum().toDouble()
        var t = if (timeSeconds <= 0.0) 0.0 else timeSeconds % total
        durations.forEachIndexed { i, d ->
            if (t < d) return i to t.toFloat()
            t -= d
        }
        return durations.lastIndex to durations.last()
    }
}

/** Preset viewing angles. Yaw rotates the model about its vertical axis. */
enum class ViewAngle(val label: String, val yawDegrees: Float) {
    FRONT("Front", 0f),
    THREE_QUARTER("¾", 35f),
    SIDE("Side", 90f),
    BACK("Back", 180f),
}

/**
 * Camera angles that show the coach for this clip sequence. A wall prop hides the coach from the side it stands on:
 * the wall push-up faces its wall (front and ¾ looked at the back of the wall only), the wall sit leans on one (back).
 */
fun viewAngles(sequence: List<String>): List<ViewAngle> {
    val wallInFront = sequence.any { it in WALL_IN_FRONT }
    val wallBehind = sequence.any { it in WALL_BEHIND }
    return ViewAngle.entries.filter {
        !(wallInFront && (it == ViewAngle.FRONT || it == ViewAngle.THREE_QUARTER)) && !(wallBehind && it == ViewAngle.BACK)
    }
}

private val WALL_IN_FRONT = setOf("wall_pushup")
private val WALL_BEHIND = setOf("wall_sit")

/** Best starting camera for a lesson, from its recommended view (side-on movements start side-on). */
fun defaultViewAngle(recommendedView: String?): ViewAngle = when (recommendedView) {
    "side" -> ViewAngle.SIDE
    "front_or_diagonal" -> ViewAngle.THREE_QUARTER
    "front_or_side" -> ViewAngle.THREE_QUARTER
    else -> ViewAngle.FRONT
}
